head.b:skin:
    :root{--bg:#080910;--panel:#11131d;--panel2:#171a27;--text:#f8f8fb;--muted:#a7a9b8;--orange:#ff641c;--pink:#ff3e72;--line:rgba(255,255,255,.1)}
    *{box-sizing:border-box}
    html,body{margin:0;min-height:100%;background:var(--bg);color:var(--text);font-family:Arial,Helvetica,sans-serif}
    body{overflow-x:hidden}
    a{color:inherit;text-decoration:none}
    button,input{font:inherit}
    .trc-app{min-height:100vh;background:radial-gradient(ellipse at 75% 0%,rgba(95,34,143,.13),transparent 38%),var(--bg);padding-bottom:82px}
    .trc-header{height:68px;display:flex;align-items:center;justify-content:space-between;padding:0 max(4vw,17px);border-bottom:1px solid var(--line);background:rgba(8,9,16,.96);position:sticky;top:0;z-index:30}
    .trc-menu-toggle{border:0;background:none;color:#fff;font-size:29px;line-height:1;padding:6px;cursor:pointer}
    .trc-head-actions{display:flex;gap:18px;align-items:center}
    .trc-head-actions button{background:none;border:0;color:#fff;font-size:23px;cursor:pointer}
    .trc-more{font-size:29px!important;letter-spacing:2px;padding:0 4px}
    .trc-menu-panel{display:none;position:absolute;left:14px;top:60px;width:min(285px,82vw);padding:14px;background:#171925;border:1px solid rgba(255,255,255,.16);border-radius:17px;box-shadow:0 16px 45px #000b;z-index:55}
    .trc-menu-panel.open{display:block}
    .trc-menu-brand{display:flex;align-items:center;gap:10px;padding:7px 5px 14px;margin-bottom:8px;border-bottom:1px solid var(--line);font-size:16px;font-weight:900;letter-spacing:.7px;line-height:1.15}
    .trc-menu-brand .trc-mark{width:39px;height:39px;flex:0 0 39px}
    .trc-menu-link{display:block;width:100%;padding:12px 9px;border:0;background:none;color:#f8f8fb;text-align:left;font-size:15px;border-radius:9px;cursor:pointer}
    .trc-menu-link:active,.trc-menu-link:hover{background:#ffffff12}
    .trc-brand{display:flex;align-items:center;gap:10px;font-size:25px;font-weight:900;letter-spacing:-1px}
    .trc-mark{width:36px;height:36px;border-radius:11px;background:linear-gradient(135deg,#ff8c00,#ff3d20);display:grid;place-items:center;box-shadow:0 5px 20px #ff531c44}
    .trc-mark:after{content:'';margin-left:3px;border-top:8px solid transparent;border-bottom:8px solid transparent;border-left:12px solid #fff}
    .trc-brand-name{display:block;color:#f8f8fb;font-size:18px;font-weight:900;letter-spacing:1.1px;line-height:1.1}
    .trc-head-actions{display:flex;gap:18px;align-items:center}
    .trc-head-actions button{background:none;border:0;color:#fff;font-size:23px;cursor:pointer}
    .trc-search{display:none;position:absolute;right:15px;top:59px;width:min(330px,85vw);background:#171925;border:1px solid var(--line);border-radius:24px;padding:11px 15px;color:white;outline:none}
    .trc-search.open{display:block}
    .trc-main{max-width:1180px;margin:0 auto;padding:0 18px}
    .trc-screen{display:none}
    .trc-screen.active{display:block}
    .trc-feed-card{height:min(720px,calc(100vh - 205px));min-height:520px;max-width:520px;margin:16px auto 24px;position:relative;overflow:hidden;border-radius:22px;background:linear-gradient(145deg,#28134b,#a32e68 58%,#f17a42);box-shadow:0 18px 55px #0008}
    .trc-feed-card:nth-child(2n){background:linear-gradient(145deg,#052e4a,#266b8c 58%,#a34e7a)}
    .trc-cover-bg{position:absolute;inset:0;background:radial-gradient(circle at 65% 30%,#ffb4d044,transparent 32%),linear-gradient(180deg,transparent 35%,#000b 100%)}
    .trc-cover-symbol{position:absolute;inset:0;display:grid;place-items:center;font-size:210px;font-weight:900;color:#ffffff22}
    .trc-feed-card .trc-cover-img{position:absolute;width:100%;height:100%;inset:0;object-fit:cover}
    .trc-feed-card:after{content:'';position:absolute;inset:0;background:linear-gradient(180deg,#0005 0%,transparent 28%,transparent 48%,#000c 100%);pointer-events:none}
    .trc-feed-info{position:absolute;left:20px;right:20px;bottom:82px;z-index:3;text-shadow:0 2px 9px #000}
    .trc-eyebrow{font-size:10px;letter-spacing:2px;color:#ffd2bc;font-weight:800;margin-bottom:8px}
    .trc-feed-info h2{font-size:25px;line-height:1.12;margin:0 0 6px}
    .trc-feed-info p{font-size:13px;color:#e5e1eb;margin:0 0 7px}
    .trc-feed-info .trc-caption{font-size:12px;color:#d7d3df;line-height:1.4}
    .trc-side-actions{position:absolute;left:18px;right:18px;bottom:22px;z-index:4;display:flex;flex-direction:row;gap:8px;align-items:center;justify-content:space-between}
    .trc-action{border:0;background:none;color:#fff;display:flex;flex-direction:row;align-items:center;justify-content:center;gap:6px;text-shadow:0 2px 7px #000;cursor:pointer;padding:4px 2px;min-width:0;white-space:nowrap}
    .trc-action span{font-size:29px;line-height:1;display:inline-flex;align-items:center;justify-content:center}
    .trc-action small{font-size:10px;font-weight:700}.trc-action small b{font-size:10px}.trc-comment-icon{width:27px;height:24px;border-radius:9px;background:#fff;color:#25202c!important;font-size:0!important;position:relative;letter-spacing:1px}.trc-comment-icon:before{content:'';position:absolute;left:6px;top:10px;width:4px;height:4px;border-radius:50%;background:#25202c;box-shadow:7px 0 0 #25202c,14px 0 0 #25202c}.trc-comment-icon:after{content:'';position:absolute;left:5px;bottom:-4px;border-width:5px 5px 0 0;border-style:solid;border-color:#fff transparent transparent transparent}
    .trc-action.liked span{color:#ff315f}
    .trc-record{display:none;position:absolute;right:17px;bottom:22px;width:48px;height:48px;border:7px solid #191922;border-radius:50%;background:radial-gradient(circle,#fff 0 8%,#333 10% 21%,#090910 23% 100%);z-index:3;box-shadow:0 0 0 2px #ffffff55}
    .trc-section-title{display:flex;align-items:center;justify-content:space-between;margin:25px 0 16px}
    .trc-section-title h2{font-size:23px;margin:0;letter-spacing:-.5px}
    .trc-section-title a{font-size:12px;color:#ff9a62;font-weight:700}
    .trc-feature{display:grid;grid-template-columns:1.15fr .85fr;gap:16px;margin:20px 0 25px}
    .trc-feature-banner{min-height:190px;border-radius:18px;padding:24px;display:flex;flex-direction:column;justify-content:end;background:linear-gradient(115deg,#32135b,#a22e78 65%,#ed684d);position:relative;overflow:hidden}
    .trc-feature-banner:after{content:'♫';position:absolute;right:18px;top:-28px;font-size:180px;color:#ffffff1c}
    .trc-feature-banner small{z-index:1;color:#ffd2e5;font-weight:700;letter-spacing:1.4px}
    .trc-feature-banner h2{z-index:1;font-size:27px;line-height:1.05;margin:8px 0}
    .trc-feature-banner p{z-index:1;margin:0;color:#f4d9e9;font-size:12px}
    .trc-categories{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
    .trc-category{border-radius:15px;padding:18px 10px;min-height:82px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:7px;font-weight:700;background:linear-gradient(135deg,#301b48,#171827);border:1px solid var(--line)}
    .trc-category:nth-child(2){background:linear-gradient(135deg,#3b1746,#20182b)}
    .trc-category:nth-child(3){background:linear-gradient(135deg,#123d59,#172333)}
    .trc-category:nth-child(4){background:linear-gradient(135deg,#17402e,#172820)}
    .trc-category b{font-size:24px}
    .trc-song-list{display:flex;flex-direction:column;gap:9px}
    .trc-song{display:flex;align-items:center;gap:12px;padding:8px;border-radius:13px;background:#121420;border:1px solid #ffffff09}
    .trc-song-cover{width:54px;height:54px;flex:0 0 54px;border-radius:9px;display:grid;place-items:center;font-size:24px;background:linear-gradient(135deg,#ff4c6c,#55207d)}
    .trc-song:nth-child(2) .trc-song-cover{background:linear-gradient(135deg,#12618b,#4bb1b2)}
    .trc-song:nth-child(3) .trc-song-cover{background:linear-gradient(135deg,#4b1b73,#ce467c)}
    .trc-song:nth-child(4) .trc-song-cover{background:linear-gradient(135deg,#714021,#e9a04c)}
    .trc-song-info{min-width:0;flex:1}
    .trc-song-info b{display:block;font-size:14px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
    .trc-song-info small{color:var(--muted);font-size:11px}
    .trc-play{width:34px;height:34px;border:0;border-radius:50%;background:#ffffff1a;color:#fff;cursor:pointer}
    .trc-playlists{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .trc-playlist{border-radius:14px;overflow:hidden;background:#151622}
    .trc-playlist-art{aspect-ratio:1/1;display:grid;place-items:center;font-size:44px;background:linear-gradient(135deg,#ab20c5,#ff4c96)}
    .trc-playlist:nth-child(2) .trc-playlist-art{background:linear-gradient(135deg,#ed8c69,#48245d)}
    .trc-playlist:nth-child(3) .trc-playlist-art{background:linear-gradient(135deg,#191919,#d36b22)}
    .trc-playlist b{display:block;font-size:12px;padding:8px 9px 1px}
    .trc-playlist small{display:block;color:var(--muted);font-size:10px;padding:0 9px 10px}
    .trc-player{max-width:540px;margin:20px auto 35px;padding:18px;border-radius:23px;background:linear-gradient(155deg,#21152e,#12131e 65%,#311221);border:1px solid var(--line)}
    .trc-player-art{width:100%;aspect-ratio:1/1;max-height:440px;border-radius:17px;display:grid;place-items:center;font-size:100px;background:radial-gradient(circle at 50% 42%,#ff315e,#5d123e 42%,#090910 78%);box-shadow:0 14px 40px #0008}
    .trc-player-title{display:flex;align-items:center;justify-content:space-between;margin:20px 0 12px}
    .trc-player-title h2{font-size:23px;margin:0 0 3px}
    .trc-player-title p{color:var(--muted);margin:0;font-size:13px}
    .trc-heart{border:0;background:none;color:#ff315f;font-size:25px}
    .trc-progress{width:100%;accent-color:#fff}
    .trc-times{display:flex;justify-content:space-between;color:#c6c4ce;font-size:10px}
    .trc-controls{display:flex;justify-content:center;align-items:center;gap:27px;margin:20px 0}
    .trc-controls button{background:none;border:0;color:#fff;font-size:24px;cursor:pointer}
    .trc-controls .main{height:56px;width:56px;border-radius:50%;background:#fff;color:#111;font-size:22px}
    .trc-player-tools{display:flex;justify-content:space-around;color:#d5d3dd;font-size:11px}
    .trc-player-tools span{display:flex;flex-direction:column;align-items:center;gap:5px}
    .trc-player-tools b{font-size:19px}
    .trc-library-empty{text-align:center;padding:55px 15px;color:var(--muted)}
    .trc-bottom{height:82px;position:fixed;left:0;right:0;bottom:0;z-index:40;background:rgba(15,16,26,.97);border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-around;padding:5px 5px calc(5px + env(safe-area-inset-bottom));backdrop-filter:blur(14px)}
    .trc-bottom button{flex:1;max-width:20%;border:0;background:none;color:#aaa;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;font-size:10px;cursor:pointer;min-width:0;padding:3px 0}
    .trc-bottom button span{font-size:21px;line-height:1}
    .trc-bottom button.active{color:#ff711e}
    .trc-bottom .trc-bottom-play{flex:0 0 62px;width:62px;height:62px;max-width:62px;min-width:62px;border:2px solid #fff;border-radius:50%;color:#fff;display:grid;place-items:center;padding:0;margin-top:-13px;background:rgba(255,255,255,.035);box-shadow:0 0 0 1px #ffffff18,0 0 22px #8d26cf22;font-size:0;line-height:1}
    .trc-bottom .trc-bottom-play span{font-size:25px;line-height:1;margin-left:3px}
    .trc-bottom .trc-bottom-play.playing span{font-size:23px;margin-left:0}
    .trc-app{padding-bottom:98px}
    .trc-toast{position:fixed;left:50%;bottom:80px;transform:translateX(-50%);z-index:60;background:#282837;color:#fff;border-radius:22px;padding:9px 15px;font-size:12px;opacity:0;pointer-events:none;transition:opacity .2s}
    .trc-toast.show{opacity:1}
    .trc-main{max-width:none;margin:0 auto;padding:0 14px}
    .trc-feed-scroll{height:calc(100dvh - 136px);min-height:430px;overflow-y:auto;overflow-x:hidden;overscroll-behavior-y:contain;scroll-snap-type:y mandatory;scrollbar-width:none;padding:0 0 8px}
    .trc-feed-scroll::-webkit-scrollbar{display:none}
    .trc-demo-card{height:calc(100% - 8px);min-height:430px;margin:0 auto 8px;scroll-snap-align:start;scroll-snap-stop:always;max-width:620px;width:100%;border-radius:0 0 20px 20px}
    .trc-demo-card .trc-cover-img{display:block;position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
    .trc-demo-card .trc-cover-bg{z-index:1;background:linear-gradient(180deg,rgba(8,9,16,.05) 20%,rgba(8,9,16,.08) 45%,rgba(8,9,16,.92) 100%)}
    .trc-demo-card .trc-feed-info,.trc-demo-card .trc-side-actions,.trc-demo-card .trc-record{z-index:3}
    .trc-demo-card .trc-feed-info{left:20px;right:92px;bottom:24px}
    .trc-demo-card .trc-feed-info h2{font-size:30px}
    .trc-demo-card .trc-side-actions{bottom:100px;gap:22px}
    .trc-demo-card .trc-action small b{font-size:10px;margin-left:3px}
    .trc-demo-card .trc-action span{font-size:29px}
    .trc-demo-card .trc-action.liked span{color:#ff315f}
    .blogger-hidden{
      display:block!important;position:absolute!important;left:-12000px!important;top:0!important;
      width:min(620px,100vw)!important;max-width:620px!important;height:auto!important;
      overflow:visible!important;opacity:0!important;pointer-events:none!important;z-index:-1!important
    }
    @media(max-width:600px){.trc-main{padding:0 14px}.trc-feature{grid-template-columns:1fr}.trc-categories{grid-template-columns:repeat(4,1fr)}.trc-category{padding:12px 3px;min-height:75px;font-size:10px}.trc-category b{font-size:20px}.trc-feed-scroll{height:calc(100dvh - 136px);min-height:430px}.trc-demo-card{height:calc(100% - 8px);min-height:430px;margin:0 auto 8px}.trc-playlists{gap:8px}}
    @media(min-width:900px){.trc-app{max-width:1180px;margin:0 auto}.trc-feed-card{max-width:460px}}

    /* TRC feed card layout fix: artwork first, metadata next, actions last */
    .trc-demo-card{height:auto!important;min-height:0!important;display:flex;flex-direction:column;position:relative;overflow:hidden;margin:14px auto 22px!important;background:#090812!important}
    .trc-demo-card .trc-cover-img{position:relative!important;inset:auto!important;display:block;width:100%!important;height:clamp(220px,36vh,300px)!important;min-height:220px!important;max-height:300px;object-fit:cover!important;object-position:center center!important;flex:0 0 auto}
    .trc-demo-card .trc-cover-bg,.trc-demo-card .trc-cover-symbol{display:none!important}
    .trc-demo-card:after{display:none!important}
    .trc-demo-card .trc-feed-info{position:relative!important;left:auto!important;right:auto!important;top:auto!important;bottom:auto!important;order:2;padding:18px 20px 8px;background:linear-gradient(180deg,#11101b 0%,#090812 100%);text-shadow:none;}
    .trc-demo-card .trc-eyebrow{font-size:10px;letter-spacing:2px;margin-bottom:9px}
    .trc-demo-card .trc-feed-info h2{font-size:30px;line-height:1.12;margin:0 0 7px}
    .trc-demo-card .trc-feed-info p{font-size:14px;margin:0 0 8px;color:#e5e1eb}
    .trc-demo-card .trc-feed-info .trc-caption{font-size:13px;line-height:1.45;color:#d7d3df}
    .trc-demo-card .trc-side-actions{position:relative!important;left:auto!important;right:auto!important;top:auto!important;bottom:auto!important;order:3;display:flex;flex-direction:row;align-items:center;justify-content:space-around;gap:4px;padding:12px 12px 18px;margin:0;background:#090812;}
    .trc-demo-card .trc-action{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;padding:4px 2px;white-space:nowrap}
    .trc-demo-card .trc-action span{font-size:30px;line-height:1.1}
    .trc-demo-card .trc-action small{font-size:11px;font-weight:700}
    .trc-demo-card .trc-action small b{font-size:11px;margin-left:3px}
    .trc-demo-card .trc-record{display:none!important}
    @media(max-width:600px){.trc-demo-card{width:100%;max-width:520px}.trc-demo-card .trc-cover-img{height:clamp(220px,36vh,300px)!important;min-height:220px!important;max-height:300px!important}.trc-demo-card .trc-feed-info{padding:16px 18px 7px}.trc-demo-card .trc-feed-info h2{font-size:28px}.trc-demo-card .trc-side-actions{padding:10px 8px 16px}}


    /* TRC album artwork + lyrics refinement */
    .trc-demo-card{max-width:620px!important;width:100%;background:#090812!important}
    .trc-demo-card .trc-cover-img{
      position:relative!important;inset:auto!important;display:block!important;
      width:calc(100% - 22px)!important;height:auto!important;aspect-ratio:1/1!important;
      min-height:0!important;max-height:none!important;object-fit:cover!important;
      object-position:center!important;flex:0 0 auto;margin:12px auto 0!important;
      border-radius:18px!important;
    }
    .trc-demo-card .trc-feed-info{padding:16px 20px 8px!important}
    .trc-demo-card .trc-lyrics{display:flex;flex-direction:column;gap:5px;margin:0 0 18px;color:#bdb8ca;font-size:15px;line-height:1.45;font-weight:500}
    .trc-demo-card .trc-lyrics span:first-child{color:#f1edf8}
    .trc-demo-card .trc-eyebrow{margin-bottom:8px}
    .trc-demo-card .trc-feed-info h2{font-size:28px;line-height:1.12;margin:0 0 7px}
    .trc-demo-card .trc-feed-info p{font-size:15px;margin:0 0 8px}
    .trc-demo-card .trc-side-actions{padding:10px 12px 18px!important}
    .trc-demo-card .trc-action{gap:5px}
    .trc-demo-card .trc-action small,.trc-demo-card .trc-action small b{font-size:12px}
    @media(max-width:600px){
      .trc-demo-card{width:100%;max-width:620px!important}
      .trc-demo-card .trc-cover-img{width:calc(100% - 22px)!important;aspect-ratio:1/1!important;height:auto!important}
      .trc-demo-card .trc-feed-info{padding:15px 18px 7px!important}
      .trc-demo-card .trc-lyrics{font-size:14px;margin-bottom:16px}
      .trc-demo-card .trc-feed-info h2{font-size:27px}
    }

    /* Final mobile sizing: square album art, reference-style engagement row, compact center play */
    .trc-demo-card .trc-cover-img{
      width:calc(100% - 22px)!important;
      height:clamp(280px, calc(100vw - 50px), 560px)!important;
      aspect-ratio:1/1!important;
      min-height:0!important;
      max-height:560px!important;
      object-fit:cover!important;
      border-radius:18px!important;
    }
    .trc-demo-card .trc-side-actions{
      display:flex!important;
      flex-direction:row!important;
      align-items:center!important;
      justify-content:space-around!important;
      gap:8px!important;
      padding:12px 12px 18px!important;
    }
    .trc-demo-card .trc-action{
      flex-direction:row!important;
      align-items:center!important;
      justify-content:center!important;
      gap:9px!important;
      min-width:0!important;
    }
    .trc-demo-card .trc-action span{
      font-size:36px!important;
      line-height:1!important;
    }
    .trc-demo-card .trc-action small,
    .trc-demo-card .trc-action small b{
      font-size:14px!important;
      margin:0!important;
    }
    .trc-bottom .trc-bottom-play{
      flex:0 0 42px!important;
      width:42px!important;
      height:42px!important;
      min-width:42px!important;
      max-width:42px!important;
      border-width:2px!important;
      margin-top:-7px!important;
    }
    .trc-bottom .trc-bottom-play span{
      font-size:18px!important;
      margin-left:2px!important;
    }
    .trc-bottom .trc-bottom-play.playing span{
      font-size:17px!important;
      margin-left:0!important;
    }
    @media(max-width:600px){
      .trc-demo-card .trc-cover-img{height:calc(100vw - 50px)!important;max-height:560px!important;}
      .trc-demo-card .trc-action span{font-size:36px!important;}
      .trc-demo-card .trc-action small,.trc-demo-card .trc-action small b{font-size:14px!important;}
    }

    /* Compact artwork and smaller center play control */
    .trc-demo-card .trc-cover-img{
      display:block!important; width:min(78%,390px)!important; max-width:390px!important;
      height:auto!important; aspect-ratio:1/1!important; min-height:0!important;
      max-height:none!important; object-fit:cover!important; margin:12px auto 0!important;
      border-radius:18px!important;
    }
    .trc-bottom .trc-bottom-play{
      box-sizing:border-box!important; flex:0 0 46px!important;
      width:46px!important; height:46px!important; min-width:46px!important;
      max-width:46px!important; min-height:46px!important; max-height:46px!important;
      padding:0!important; margin-top:-5px!important; border-width:2px!important;
    }
    .trc-bottom .trc-bottom-play span{font-size:19px!important;line-height:1!important;margin-left:2px!important}
    .trc-bottom .trc-bottom-play.playing span{font-size:18px!important;margin-left:0!important}
    @media(max-width:600px){
      .trc-demo-card .trc-cover-img{width:min(78%,390px)!important;height:auto!important;max-height:none!important}
    }

    /* TRC SIGNATURE REDESIGN — premium dark / electric orange */
    :root{--bg:#08090f;--panel:#11131b;--panel2:#191c27;--text:#f7f7fb;--muted:#9b9eae;--orange:#ff6a2a;--pink:#ff416d;--line:rgba(255,255,255,.09)}
    html,body{background:#08090f;color:var(--text)}
    .trc-app{background:radial-gradient(ellipse at 50% -12%,rgba(255,106,42,.13),transparent 34%),radial-gradient(ellipse at 100% 40%,rgba(104,54,166,.09),transparent 38%),#08090f;padding-bottom:100px}
    .trc-header{height:72px;padding:0 20px;background:rgba(8,9,15,.88);border-bottom:1px solid rgba(255,255,255,.07);backdrop-filter:blur(22px);-webkit-backdrop-filter:blur(22px)}
    .trc-header:after{content:"TRC MUSIC";position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);font-size:14px;font-weight:900;letter-spacing:2.6px;color:#f7f7fb;pointer-events:none}
    .trc-menu-toggle{font-size:27px;color:#f8f8fb;width:42px;height:42px;border-radius:14px;background:#ffffff08}
    .trc-head-actions{gap:8px}
    .trc-head-actions button{width:42px;height:42px;border-radius:14px;background:#ffffff08;font-size:25px}
    .trc-menu-panel{top:62px;background:#151722;border:1px solid #ffffff18;border-radius:20px;backdrop-filter:blur(20px)}
    .trc-main{padding:0 12px}
    .trc-feed-scroll{height:calc(100dvh - 154px);padding:10px 0 20px;scroll-padding-top:10px}
    .trc-demo-card{max-width:510px!important;width:100%;margin:0 auto 22px!important;padding:0 0 8px!important;border:1px solid rgba(255,255,255,.075);border-radius:26px!important;background:linear-gradient(160deg,#171522 0%,#0d0e16 62%,#111019 100%)!important;box-shadow:0 18px 50px rgba(0,0,0,.42),inset 0 1px 0 rgba(255,255,255,.035)}
    .trc-demo-card .trc-cover-img{width:calc(100% - 28px)!important;max-width:430px!important;margin:14px auto 0!important;border-radius:21px!important;box-shadow:0 12px 34px rgba(0,0,0,.35)}
    .trc-demo-card .trc-feed-info{padding:19px 22px 8px!important;background:transparent!important}
    .trc-demo-card .trc-lyrics{font-size:13px!important;line-height:1.55!important;gap:3px!important;margin:0 0 15px!important;color:#a9a6b7!important}
    .trc-demo-card .trc-lyrics span:first-child{color:#ffb18d!important;font-weight:700}
    .trc-demo-card .trc-eyebrow{color:#ff9a6b!important;font-size:9px;letter-spacing:2.2px}
    .trc-demo-card .trc-feed-info h2{font-size:31px!important;font-weight:850;letter-spacing:-1px;line-height:1.08;margin:0 0 6px!important}
    .trc-demo-card .trc-feed-info p{font-size:14px!important;color:#b9bac7!important;margin:0!important}
    .trc-demo-card .trc-side-actions{padding:13px 18px 15px!important;margin:4px 10px 0!important;border-top:1px solid rgba(255,255,255,.07);background:transparent!important}
    .trc-demo-card .trc-action{gap:8px!important;color:#f6f5fa!important}
    .trc-demo-card .trc-action span{font-size:27px!important}
    .trc-demo-card .trc-action small,.trc-demo-card .trc-action small b{font-size:12px!important;color:#d7d5df}
    .trc-demo-card .trc-action.liked span{color:#ff456d!important}
    .trc-demo-card .trc-comment-icon{width:25px;height:22px;background:#f5f3fa!important}
    .trc-demo-card .trc-comment-icon:before{background:#22212a!important;box-shadow:7px 0 0 #22212a,14px 0 0 #22212a}
    .trc-demo-card .trc-comment-icon:after{border-top-color:#f5f3fa!important}
    .trc-bottom{height:86px;padding:7px 7px calc(7px + env(safe-area-inset-bottom));background:rgba(12,13,21,.92);border-top:1px solid rgba(255,255,255,.08);backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px)}
    .trc-bottom button{color:#777b8c;font-size:10px;font-weight:600;gap:5px}
    .trc-bottom button span{font-size:21px}
    .trc-bottom button.active{color:#ff793e}
    .trc-bottom .trc-bottom-play{background:linear-gradient(145deg,#ff8a42,#ff5424)!important;border:0!important;color:#fff!important;box-shadow:0 5px 22px rgba(255,95,39,.35)!important;margin-top:-17px!important;width:52px!important;height:52px!important;min-width:52px!important;max-width:52px!important;flex-basis:52px!important}
    .trc-bottom .trc-bottom-play span{font-size:21px!important;margin-left:3px!important}
    .trc-bottom .trc-bottom-play.playing span{font-size:19px!important}
    .trc-section-title{margin:26px 4px 15px}
    .trc-section-title h2{font-size:21px;font-weight:850;letter-spacing:-.6px}
    .trc-section-title a{color:#ff8954}
    .trc-feature-banner{border:1px solid #ffffff12;border-radius:22px;background:linear-gradient(125deg,#321c43,#8d315d 60%,#e65c37);box-shadow:0 14px 34px #0005}
    .trc-category{border-radius:17px;background:linear-gradient(145deg,#191b28,#11131d)!important;border:1px solid #ffffff0d}
    .trc-song{border-radius:16px;background:#12141e;border:1px solid #ffffff0b;padding:9px}
    .trc-song-cover{border-radius:12px}
    .trc-play{background:#ff6a2a;color:#fff;box-shadow:0 4px 12px #ff6a2a35}
    .trc-playlist{border:1px solid #ffffff0b;border-radius:17px;background:#12141e}
    .trc-player{border-radius:26px;background:linear-gradient(155deg,#1a1724,#10121b 70%);box-shadow:0 18px 50px #0006}
    .trc-player-art{border-radius:21px}
    .trc-controls .main{background:linear-gradient(145deg,#ff8a42,#ff5424);color:#fff;box-shadow:0 6px 20px #ff642f44}
    .trc-toast{background:#242532;border:1px solid #ffffff14;box-shadow:0 8px 24px #0007}
    @media(max-width:600px){
      .trc-main{padding:0 12px}
      .trc-feed-scroll{height:calc(100dvh - 158px);min-height:420px}
      .trc-demo-card{border-radius:24px!important}
      .trc-demo-card .trc-cover-img{width:calc(100% - 26px)!important;margin-top:13px!important}
      .trc-demo-card .trc-feed-info{padding:17px 19px 8px!important}
      .trc-demo-card .trc-feed-info h2{font-size:29px!important}
      .trc-demo-card .trc-side-actions{padding:12px 12px 14px!important}
      .trc-demo-card .trc-action span{font-size:26px!important}
    }
    @media(min-width:900px){.trc-app{max-width:1180px}.trc-feed-scroll{height:calc(100vh - 160px)}}


    /* Swipeable album / lyrics stage */
    .trc-demo-card{padding-bottom:5px!important;overflow:hidden!important}
    .trc-demo-card .trc-swipe-stage{
      position:relative;width:min(70%,350px);aspect-ratio:1/1;margin:14px auto 0;
      overflow:hidden;border-radius:20px;background:linear-gradient(145deg,#21172f,#10121c);
      box-shadow:0 12px 30px rgba(0,0,0,.34);touch-action:pan-y;isolation:isolate
    }
    .trc-demo-card .trc-swipe-stage .trc-cover-img{
      position:absolute!important;inset:0!important;width:100%!important;height:100%!important;
      max-width:none!important;max-height:none!important;margin:0!important;border-radius:0!important;
      object-fit:cover!important;transition:transform .42s cubic-bezier(.2,.75,.25,1),opacity .32s ease;
      will-change:transform;z-index:2
    }
    .trc-demo-card .trc-swipe-stage .trc-lyrics{
      position:absolute;inset:0;display:flex!important;flex-direction:column;justify-content:center;
      padding:24px!important;margin:0!important;gap:14px!important;font-size:16px!important;
      line-height:1.65!important;background:radial-gradient(circle at 80% 10%,rgba(255,106,42,.19),transparent 45%),linear-gradient(145deg,#21172f,#10121c);
      transform:translateX(105%);transition:transform .42s cubic-bezier(.2,.75,.25,1);
      overflow:auto;z-index:1
    }
    .trc-demo-card .trc-swipe-stage .trc-lyrics span:first-child{color:#ffb18d!important}
    .trc-demo-card.show-lyrics .trc-swipe-stage .trc-cover-img{transform:translateX(-105%)}
    .trc-demo-card.show-lyrics .trc-swipe-stage .trc-lyrics{transform:translateX(0)}
    .trc-demo-card .trc-swipe-hint{
      position:absolute;right:10px;bottom:10px;z-index:4;padding:6px 9px;border-radius:20px;
      background:rgba(5,6,12,.62);color:#fff;font-size:10px;letter-spacing:.3px;
      opacity:.82;pointer-events:none;backdrop-filter:blur(8px)
    }
    .trc-demo-card.show-lyrics .trc-swipe-hint{display:none}
    .trc-demo-card .trc-feed-info{padding-top:15px!important}
    .trc-demo-card .trc-feed-info h2{margin-top:0!important}
    @media(max-width:600px){
      .trc-demo-card .trc-swipe-stage{width:70%;max-width:310px;margin-top:13px;border-radius:19px}
      .trc-demo-card .trc-swipe-stage .trc-lyrics{padding:20px!important;font-size:14px!important;gap:11px!important}
      .trc-demo-card .trc-feed-info{padding:14px 19px 7px!important}
    }


    /* TRC EXACT REFERENCE LOOK — orange neon frame, top transport, 4-action row */
    .trc-header{height:88px!important;padding:0 18px!important;display:flex!important;align-items:center!important;justify-content:space-between!important;background:rgba(7,8,14,.97)!important;position:sticky!important}
    .trc-header:after{content:"TRC MUSIC"!important;left:42%!important;transform:translate(-50%,-50%)!important;font-size:15px!important;letter-spacing:2.5px!important;font-weight:900!important;white-space:nowrap!important}
    .trc-menu-toggle{width:48px!important;height:48px!important;border-radius:16px!important;background:#11121a!important;font-size:28px!important}
    .trc-head-actions{gap:12px!important;margin-left:auto!important}
    .trc-head-actions button{width:48px!important;height:48px!important;border-radius:16px!important;background:#11121a!important;font-size:25px!important}
    .trc-head-actions .trc-header-play{width:52px!important;height:52px!important;border-radius:50%!important;border:3px solid #ff741f!important;background:radial-gradient(circle,#ff7626 0%,#a9360d 65%,#1a1010 100%)!important;color:#fff!important;box-shadow:0 0 8px #ff6b1b,0 0 23px #ff6b1b66!important;display:grid!important;place-items:center!important}
    .trc-header-play span{font-size:21px!important;line-height:1!important;margin-left:3px}
    .trc-header-play.playing span{font-size:18px!important;margin-left:0}
    .trc-demo-card{max-width:510px!important;width:calc(100% - 12px)!important;margin:16px auto 22px!important;padding:14px 12px 8px!important;border:2px solid #ff6a1c!important;border-radius:28px!important;background:radial-gradient(ellipse at 50% 0%,#20131b 0%,#0b0b12 60%,#08090f 100%)!important;box-shadow:0 0 5px #ff6a1c,0 0 18px #ff6a1c66,0 14px 42px #000b!important}
    .trc-demo-card .trc-swipe-stage{width:88%!important;max-width:430px!important;margin:3px auto 0!important;border-radius:23px!important;box-shadow:0 0 0 1px #ffffff16,0 10px 28px #0008!important}
    .trc-demo-card .trc-swipe-stage .trc-lyrics{background:radial-gradient(circle at 80% 10%,#ff6a2b2b,transparent 45%),linear-gradient(145deg,#21172f,#10121c)!important}
    .trc-demo-card .trc-swipe-hint{right:10px!important;bottom:10px!important;padding:8px 12px!important;font-size:11px!important;border:1px solid #ffffff1c}
    .trc-demo-card .trc-feed-info{padding:18px 12px 8px!important;background:transparent!important}
    .trc-demo-card .trc-feed-info h2{font-size:34px!important;font-weight:900!important;letter-spacing:-1.2px!important;margin:0 0 5px!important}
    .trc-demo-card .trc-feed-info p{font-size:16px!important;color:#b8bac7!important}
    .trc-demo-card .trc-side-actions{display:flex!important;flex-direction:row!important;align-items:center!important;justify-content:space-around!important;gap:0!important;padding:13px 4px 15px!important;margin:4px 4px 0!important;border-top:1px solid #ffffff20!important;background:transparent!important}
    .trc-demo-card .trc-action{flex:1!important;min-width:0!important;display:flex!important;flex-direction:row!important;align-items:center!important;justify-content:center!important;gap:7px!important;padding:4px 2px!important;white-space:nowrap!important}
    .trc-demo-card .trc-action span{font-size:29px!important;line-height:1!important}
    .trc-demo-card .trc-action small,.trc-demo-card .trc-action small b{font-size:13px!important;color:#f5f4f8!important}
    .trc-demo-card .trc-whatsapp-icon{width:31px!important;height:31px!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;flex:0 0 31px!important;background:#fff!important;border-radius:50%!important;color:#08090f!important}
    .trc-demo-card .trc-whatsapp-icon svg{display:block!important;width:25px!important;height:25px!important;fill:#08090f!important}
    .trc-demo-card .trc-share-action span{font-size:32px!important}
    .trc-bottom{height:82px!important;justify-content:space-around!important;padding:6px 5px calc(6px + env(safe-area-inset-bottom))!important}
    .trc-bottom button{flex:1!important;max-width:20%!important;font-size:12px!important;gap:7px!important}
    .trc-bottom button span{font-size:25px!important}
    .trc-bottom button.active{color:#ff741f!important}
