    /* TRC modern violet music-app redesign */
    :root{--bg:#100e19;--panel:#211e2c;--panel2:#292536;--text:#f7f5fb;--muted:#aaa3b8;--accent:#a75cf0;--accent2:#d15bdb}
    body,.trc-app{background:#100e19!important;color:var(--text)!important}
    .trc-header{height:78px!important;background:#100e19!important;border:0!important;padding:0 17px!important;display:flex!important;align-items:center!important;justify-content:space-between!important}
    .trc-header:after{display:none!important}
    .trc-wordmark{display:flex;flex-direction:column;align-items:flex-start;text-decoration:none;font-weight:900;line-height:.82;letter-spacing:-1px;margin-left:7px;margin-right:auto}
    .trc-wordmark span{font-size:28px;background:linear-gradient(90deg,#43d6ec,#bd65ef,#ff5da7);background-clip:text;-webkit-background-clip:text;color:transparent}
    .trc-wordmark b{font-size:17px;color:#fff;letter-spacing:1px}
    .trc-head-actions{display:flex!important;gap:14px!important;align-items:center!important}
    .trc-menu-toggle,#trcSearchToggle{width:42px!important;height:42px!important;border-radius:13px!important;background:#211e2c!important;color:#fff!important;border:0!important}
    .trc-header-play{width:38px!important;height:38px!important;border-radius:50%!important;background:linear-gradient(145deg,#c06af6,#8152e8)!important;color:white!important;border:0!important;box-shadow:0 0 18px #a75cf066!important}
    .trc-main{padding:12px 15px 95px!important;max-width:720px!important;margin:auto!important}
    .trc-screen{display:none}.trc-screen.active{display:block}
    .trc-home-heading{display:flex;align-items:center;justify-content:space-between;margin:7px 2px 12px}
    .trc-home-heading h1,.trc-home-heading h2{font-size:21px;font-weight:800;margin:0;color:#fff}
    .trc-home-heading button,.trc-home-heading a{background:none;border:0;color:#bba1d6;text-decoration:none;font-size:13px}
    .trc-live-pill{border-radius:10px;padding:10px 14px;background:linear-gradient(100deg,#c64fc6,#7755e9);font-weight:800;font-size:14px;margin-bottom:14px}
    .trc-trending-row{display:flex;gap:10px;overflow-x:auto;padding:0 0 13px;scrollbar-width:none}
    .trc-trend-card{flex:0 0 48%;max-width:190px;text-align:left;border:0;border-radius:13px;background:#242130;color:#fff;padding:8px;overflow:hidden}
    .trc-trend-card img{width:100%;height:112px;object-fit:cover;border-radius:9px;display:block;margin-bottom:8px}
    .trc-trend-card b{display:block;font-size:14px;margin:0 0 4px}
    .trc-trend-card small{font-size:10px;color:#c4bdcf;white-space:nowrap}
    .trc-recommended-heading{margin-top:18px!important}
    .trc-recommend-list{display:flex;flex-direction:column;gap:9px}
    .trc-recommend-item{display:flex;align-items:center;gap:10px;width:100%;border:0;border-radius:11px;background:#242130;color:#fff;padding:8px;text-align:left;min-height:68px}
    .trc-recommend-item img{width:55px;height:55px;object-fit:cover;border-radius:8px}
    .trc-recommend-item span{display:flex;flex:1;min-width:0;flex-direction:column;gap:4px}
    .trc-recommend-item b{font-size:14px}
    .trc-recommend-item small{font-size:11px;color:#bcb5c9}
    .trc-recommend-item i{font-style:normal;color:#eee;font-size:20px;padding:0 3px}
    .trc-section-title{margin:12px 0}
    .trc-section-title h2{font-size:21px}
    .trc-feature-banner{background:linear-gradient(120deg,#9d4ac5,#4c3c8e);border-radius:15px;padding:22px}
    .trc-categories{display:flex;gap:8px;margin:14px 0}
    .trc-category{background:#282435;border-radius:10px;padding:10px;flex:1;color:white;text-align:center}
    .trc-song{background:#242130;border-radius:12px}
    .trc-bottom{height:74px!important;background:#171421!important;border-top:1px solid #312b3b!important;display:flex!important;justify-content:space-around!important}
    .trc-bottom button{color:#9c94aa!important;font-size:11px!important;gap:3px!important}
    .trc-bottom button span{font-size:21px!important}
    .trc-bottom button.active{color:#bd70ed!important}
    .trc-library-head{display:flex;align-items:center;gap:14px;margin:5px 2px 18px}
    .trc-library-head h1{font-size:27px;margin:0 auto 0 0}
    .trc-library-head button{background:none;border:0;color:#fff;font-size:25px}
    .trc-library-tabs{display:flex;gap:7px;margin-bottom:20px}
    .trc-library-tabs button{flex:1;border:0;border-radius:9px;padding:9px 4px;background:#393342;color:#fff;font-weight:700;font-size:12px}
    .trc-library-tabs button.selected{background:#7550a5;box-shadow:inset 0 -3px #c46af1}
    .trc-library-subtitle{font-size:17px;margin:16px 0 11px}
    .trc-library-list{display:flex;flex-direction:column;gap:10px}
    .trc-library-row{display:flex;align-items:center;gap:12px;background:#242130;border-radius:12px;padding:10px;min-height:72px}
    .trc-library-art{width:68px;height:68px;border-radius:9px;display:grid;place-items:center;font-size:29px;color:#fff;background:linear-gradient(135deg,#5c3a8d,#d27ad7)}
    .art-two{background:linear-gradient(135deg,#192b48,#7c759e)}.art-three{background:linear-gradient(135deg,#08334d,#4c89bb)}.art-four{background:linear-gradient(135deg,#182d32,#b75fc7)}
    .trc-library-row span{display:flex;flex:1;flex-direction:column;gap:4px}
    .trc-library-row b{font-size:15px}.trc-library-row small{font-size:11px;color:#bdb6c9}
    .trc-library-row i{font-style:normal;font-size:20px;padding:0 3px}
    .trc-download-title{margin-top:25px!important}
    .trc-nowplaying-head{display:flex;justify-content:space-between;align-items:center;padding:5px 0 12px}
    .trc-nowplaying-head button{background:none;border:0;color:white;font-size:23px}
    .trc-lyrics-stage{height:55vh;min-height:360px;position:relative;overflow:hidden;border-radius:13px;background:#191426}
    .trc-lyrics-stage>img{width:100%;height:100%;object-fit:cover;filter:blur(2px) brightness(.52)}
    .trc-lyrics-overlay{position:absolute;top:36%;left:0;right:0;text-align:center;padding:18px 12px;background:#181321a8}
    .trc-lyrics-overlay p{font-size:16px;font-weight:800;margin:7px 0;color:#fff}
    .trc-lyrics-overlay strong{display:block;color:#d58afa;margin-top:10px}
    .trc-lyrics-stage>small{position:absolute;bottom:20px;left:0;right:0;text-align:center;color:#ddd}
    .trc-player{background:#211e2c;border-radius:17px;padding:17px;margin-top:12px}
    .trc-player-title h2{font-size:19px;margin:0}.trc-player-title p{font-size:12px;margin:4px 0;color:#bcb4c8}
    .trc-progress{width:100%;accent-color:#a75cf0;margin-top:15px}
