    /* Header quick actions: notification + message, matching the reference */
    /* Refined native-feeling violet header actions */
    .trc-header-quick-actions{display:flex!important;align-items:center!important;gap:12px!important;margin-left:auto!important;z-index:2!important}
    .trc-header-quick-actions .trc-header-icon{
