    .trc-single-post{max-width:620px;margin:12px auto 28px;padding:18px;border-radius:24px;background:linear-gradient(155deg,#292239,#191624 70%,#21182c);border:1px solid rgba(190,132,255,.16);box-shadow:0 18px 45px #0007;overflow:hidden}
