    /* TRC premium now-playing controls */
    .trc-single-post{background:radial-gradient(ellipse at 50% -8%,rgba(173,105,244,.22),transparent 42%),linear-gradient(155deg,#252035,#171421 72%,#21182c)!important;border:1px solid rgba(197,145,255,.2)!important;box-shadow:0 20px 55px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.055)!important}
