    .trc-lyrics-overlay{position:absolute;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;padding:25px 22px;background:linear-gradient(160deg,rgba(22,8,48,.96),rgba(7,7,18,.97));color:#fff;text-align:center;overflow:auto;opacity:0;visibility:hidden;transform:translateY(18px);transition:.28s ease}
    .trc-artwork-wrap.show-lyrics .trc-lyrics-overlay{opacity:1;visibility:visible;transform:translateY(0)}
