    @media(max-width:600px){.trc-artwork-wrap{width:min(82%,330px)}.trc-player-controls{gap:18px!important}.trc-player-controls .trc-comment-icon{width:38px;height:38px}}


    /* Player action icons: matching comment + WhatsApp controls */
    .trc-player-controls{display:flex!important;align-items:center!important;justify-content:center!important;gap:25px!important}
    .trc-player-controls .trc-comment-icon,.trc-player-controls .trc-whatsapp-share{
      width:46px!important;height:46px!important;flex:0 0 46px!important;
      display:inline-flex!important;align-items:center!important;justify-content:center!important;
      border-radius:50%!important;border:1px solid rgba(208,174,245,.24)!important;
      background:linear-gradient(145deg,rgba(151,94,194,.22),rgba(50,37,68,.58))!important;
