      fill:none!important;stroke:currentColor!important;stroke-width:1.8!important;
      stroke-linecap:round!important;stroke-linejoin:round!important
    }
    .trc-player-controls .trc-comment-icon:active,.trc-player-controls .trc-whatsapp-share:active{transform:scale(.94)}
    .trc-player-controls .trc-single-play{order:2}
    .trc-player-controls>button:first-child{order:1}
