    .trc-player-controls .trc-whatsapp-share{order:3}
    @media(max-width:600px){.trc-player-controls{gap:18px!important}.trc-player-controls .trc-comment-icon,.trc-player-controls .trc-whatsapp-share{width:43px!important;height:43px!important;flex-basis:43px!important}}


    /* Exact five-control transport layout: comment, previous, play, next, WhatsApp */
    .trc-player-controls{display:flex!important;align-items:center!important;justify-content:space-between!important;gap:0!important;width:100%!important;max-width:560px!important;margin:24px auto 8px!important;padding:0 4px!important}
    .trc-player-controls .trc-comment-icon{order:1!important}
    .trc-player-controls>button[aria-label='Previous track']{order:2!important}
    .trc-player-controls .trc-single-play{order:3!important}
    .trc-player-controls>button[aria-label='Next track']{order:4!important}
    .trc-player-controls .trc-whatsapp-share{order:5!important}
    .trc-player-controls .trc-comment-icon,
    .trc-player-controls .trc-whatsapp-share{width:46px!important;height:46px!important;flex:0 0 46px!important;border:0!important;border-radius:0!important;background:transparent!important;box-shadow:none!important;padding:0!important;color:#92919b!important}
    .trc-player-controls .trc-comment-icon:before,.trc-player-controls .trc-comment-icon:after{display:none!important;content:none!important}
    .trc-player-controls .trc-comment-icon svg,.trc-player-controls .trc-whatsapp-share svg{display:block!important;width:44px!important;height:44px!important;fill:none!important;stroke:currentColor!important;stroke-width:1.8!important;stroke-linecap:round!important;stroke-linejoin:round!important}
    .trc-player-controls>button[aria-label='Previous track'],
