    .trc-player-controls>button[aria-label='Previous track'] svg,
    .trc-player-controls>button[aria-label='Next track'] svg{width:38px!important;height:38px!important;fill:currentColor!important}
    .trc-player-controls .trc-single-play{order:3!important;width:78px!important;height:78px!important;flex:0 0 78px!important;border-radius:50%!important;background:linear-gradient(145deg,#8c42ff 0%,#a33df0 55%,#c04ce9 100%)!important;border:0!important;box-shadow:0 0 28px rgba(135,65,255,.35),inset 0 1px 0 rgba(255,255,255,.28)!important;color:#fff!important}
    .trc-player-controls .trc-single-play svg{width:34px!important;height:34px!important;fill:#fff!important}
    .trc-player-controls button:disabled{opacity:.58!important}
    @media(max-width:600px){.trc-player-controls{gap:0!important;padding:0 1px!important}.trc-player-controls .trc-comment-icon,.trc-player-controls .trc-whatsapp-share{width:42px!important;height:42px!important;flex-basis:42px!important}.trc-player-controls .trc-comment-icon svg,.trc-player-controls .trc-whatsapp-share svg{width:40px!important;height:40px!important}.trc-player-controls .trc-single-play{width:70px!important;height:70px!important;flex-basis:70px!important}.trc-player-controls>button[aria-label='Previous track'],.trc-player-controls>button[aria-label='Next track']{width:34px!important;flex-basis:34px!important}}


