    /* Final matched glyph sizing: comment and WhatsApp icons share one visual scale */
    .trc-player-controls .trc-comment-icon,
    .trc-player-controls .trc-whatsapp-share{
      width:44px!important;height:44px!important;flex:0 0 44px!important;
