    }


    /* Native Blogger comments panel opened by the player comment control */
    .trc-comments-panel{display:none;margin:18px 0 8px;padding:18px;border:1px solid rgba(190,132,255,.2);border-radius:18px;background:#1b1725;color:#f5efff;scroll-margin-top:95px}
    .trc-comments-panel .trc-comments-heading{font-size:20px;font-weight:800;color:#d8b1f3;margin:0 0 14px}
    .trc-comments-panel #comments{display:block!important;visibility:visible!important;color:#f5efff!important;padding:0!important}
    .trc-comments-panel #comments *{max-width:100%}
    .trc-comments-panel #comments a{color:#d7a4ff}
    .trc-comments-panel #comments iframe{max-width:100%}


    /* Comment panel: detach Blogger's server-rendered comments from the hidden widget */
    .trc-comments-panel{display:none;margin:18px 0 12px;padding:18px;border:1px solid rgba(190,132,255,.24);border-radius:18px;background:#211e2c;color:#f7f5fb;scroll-margin-top:100px}
    .trc-comments-panel.is-open{display:block!important}
    .trc-comments-panel .trc-comments-heading{font-size:20px;font-weight:800;color:#d8b1f3;margin:0 0 14px}
    .trc-comments-panel #comments{display:block!important;visibility:visible!important;opacity:1!important;color:#f7f5fb!important;padding:0!important}
    .trc-comments-panel #comments *{max-width:100%}
    .trc-comments-panel #comments a{color:#d8b1f3}
    .trc-comments-panel #comments iframe{display:block!important;width:100%!important;max-width:100%!important}
    .trc-comments-loading{color:#c8bfd5;font-size:14px;line-height:1.5}

    /* Native comments route: show Blogger's real form without exposing the post body/widget chrome */
    body.trc-comments-route .blogger-hidden{
      display:block!important;position:relative!important;left:0!important;top:auto!important;
      width:100%!important;max-width:620px!important;height:auto!important;overflow:visible!important;
      opacity:1!important;pointer-events:auto!important;z-index:1!important
    }
    body.trc-comments-route .blogger-hidden #Blog1{display:block!important}
    body.trc-comments-route .blogger-hidden #Blog1 .post-outer{display:none!important}
    body.trc-comments-route .blogger-hidden #Blog1 #comments{
      display:block!important;visibility:visible!important;opacity:1!important;
      max-width:620px;margin:18px auto 110px;padding:20px!important;
      border:1px solid rgba(190,132,255,.24);border-radius:18px;background:#211e2c;color:#f7f5fb
    }

    /* Embedded native Blogger comment view: keeps the music page in place */
    body.trc-comments-embed{background:#100e19!important;overflow-x:hidden!important}
    body.trc-comments-embed .trc-app{display:none!important}
    body.trc-comments-embed .blogger-hidden{
      display:block!important;position:static!important;left:auto!important;top:auto!important;
      width:100%!important;max-width:760px!important;height:auto!important;min-height:100vh!important;
      margin:0 auto!important;padding:18px!important;overflow:visible!important;opacity:1!important;
      pointer-events:auto!important;z-index:auto!important;background:#100e19!important;color:#f7f5fb!important
    }
    body.trc-comments-embed #Blog1{display:block!important}
    body.trc-comments-embed #Blog1 .post-outer{display:block!important}
    body.trc-comments-embed #Blog1 .post-title,
    body.trc-comments-embed #Blog1 .post-header,
    body.trc-comments-embed #Blog1 .post-body,
    body.trc-comments-embed #Blog1 .post-footer{display:none!important}
    body.trc-comments-embed #Blog1 #comments{display:block!important;visibility:visible!important;opacity:1!important}
    .trc-comments-panel .trc-comments-frame{
      display:block;width:100%;height:720px;max-height:78vh;border:0;border-radius:12px;
      background:#171421;color:#f7f5fb
    }
    @media(max-width:600px){.trc-comments-panel .trc-comments-frame{height:760px;max-height:80vh}}


    /* Compact inline comments: use Blogger's real form in the player page */
    .trc-comments-panel{max-width:100%;padding:15px!important;margin:16px 0 10px!important}
    .trc-comments-panel .trc-comments-content{width:100%;min-height:0;overflow:visible}
    .trc-comments-panel #comments{width:100%!important;max-width:100%!important;min-height:0!important}
    .trc-comments-panel #comments .comment-form{display:block!important;width:100%!important;margin:14px 0 0!important;padding:0!important}
    .trc-comments-panel #comments #comment-editor{display:block!important;width:100%!important;max-width:100%!important;height:170px!important;min-height:170px!important;border:1px solid rgba(190,132,255,.24)!important;border-radius:12px!important;background:#fff!important}
    .trc-comments-panel #comments .comments-content{max-height:260px;overflow-y:auto}
    .trc-comments-panel #comments .comment{padding:10px 0;border-bottom:1px solid rgba(255,255,255,.08)}
    .trc-comments-panel #comments .comment-form h4{font-size:15px;color:#d8b1f3;margin:8px 0}
    .trc-comments-panel .trc-comments-loading{font-size:13px;line-height:1.5;color:#c8bfd5}


    .trc-native-comments-link{display:inline-flex;align-items:center;justify-content:center;margin-top:12px;padding:11px 18px;border-radius:999px;background:linear-gradient(100deg,#b45be8,#7542c8);color:#fff!important;text-decoration:none!important;font-weight:700}


    .trc-header{position:sticky!important;top:0!important}
    .trc-notification-panel{position:absolute!important;right:14px!important;top:calc(100% + 8px)!important;width:min(340px,calc(100vw - 28px))!important;max-height:65vh!important;overflow:auto!important;padding:16px!important;border:1px solid rgba(190,132,255,.28)!important;border-radius:18px!important;background:#211b2d!important;box-shadow:0 18px 42px #0009!important;z-index:100!important}
    .trc-notification-panel[hidden]{display:none!important}
    .trc-notification-title{font-size:17px;font-weight:800;color:#e4b8ff;margin:0 0 12px}
    .trc-notification-item{display:block;padding:11px 4px;border-top:1px solid rgba(255,255,255,.09);text-decoration:none;color:#f7f4fb}
    .trc-notification-item small{display:block;color:#b9aec7;font-size:12px;margin-top:4px}
    .trc-notification-empty{color:#b9aec7;font-size:14px;line-height:1.5}
    @media(max-width:600px){.trc-header{position:sticky!important}.trc-notification-panel{right:10px!important;width:calc(100vw - 20px)!important}}


    /* TRC Profile access page — preserve the original official logo asset */
    #screen-profile .trc-profile-auth{width:100%;max-width:520px;margin:34px auto 110px;padding:34px 24px 38px;box-sizing:border-box;text-align:center;background:#101010;border:1px solid rgba(255,255,255,.16);border-radius:28px;box-shadow:0 18px 55px rgba(0,0,0,.38)}
    #screen-profile .trc-profile-auth-logo{width:116px;height:116px;margin:0 auto 22px;border-radius:50%;overflow:hidden;display:flex;align-items:center;justify-content:center;border:3px solid #ec2580;box-shadow:0 0 22px rgba(236,37,128,.28);background:#090909}
    #screen-profile .trc-profile-auth-logo img{display:block!important;width:100%!important;height:100%!important;max-width:100%!important;object-fit:cover!important;border-radius:50%!important}
    #screen-profile .trc-profile-auth h2{margin:0 auto 10px;color:#fff;font-size:clamp(23px,6vw,30px);line-height:1.18;font-weight:900;letter-spacing:-.7px}
    #screen-profile .trc-profile-auth h2 span{color:#ec2580}
    #screen-profile .trc-auth-subtitle{margin:0 auto 26px;color:#aaa;font-size:15px;line-height:1.5}
    #screen-profile .trc-auth-tabs{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0 0 24px}
    #screen-profile .trc-auth-tabs button{min-height:56px;border-radius:15px;border:1px solid #393939;background:#090909;color:#c9c9c9;font-size:15px;font-weight:850;cursor:pointer}
    #screen-profile .trc-auth-tabs button.active{background:#ec2580;border-color:#ec2580;color:#fff;box-shadow:0 8px 22px rgba(236,37,128,.18)}
    #screen-profile .trc-auth-form{display:grid;gap:14px}
    #screen-profile .trc-auth-form input{width:100%;height:58px;box-sizing:border-box;padding:0 18px;border-radius:15px;border:1px solid #484848;background:#080808;color:#fff;font-size:16px;outline:none}
    #screen-profile .trc-auth-form input:focus{border-color:#ec2580;box-shadow:0 0 0 3px rgba(236,37,128,.12)}
    #screen-profile .trc-auth-form input::placeholder{color:#777}
    #screen-profile .trc-signup-name{display:none}
    #screen-profile .trc-profile-auth.signup-mode .trc-signup-name{display:block}
    #screen-profile .trc-auth-submit{width:100%;min-height:62px;margin-top:4px;border:0;border-radius:15px;background:#ec2580;color:#fff;font-size:16px;font-weight:900;cursor:pointer;box-shadow:0 10px 24px rgba(236,37,128,.18)}
    #screen-profile .trc-auth-footnote{margin:22px 0 0;color:#777;font-size:12px;letter-spacing:.5px}
    @media(max-width:480px){#screen-profile .trc-profile-auth{margin:26px auto 100px;padding:30px 18px 32px;border-radius:24px}#screen-profile .trc-profile-auth-logo{width:108px;height:108px}}


/* TRC BLACK + HOT PINK CLUB THEME — visual-only override */
:root{--bg:#050505;--panel:#111;--panel2:#191919;--text:#f7f7f7;--muted:#a6a6a6;--accent:#ec247c;--accent2:#ff4d9b;--line:rgba(255,255,255,.13)}
html,body,body,.trc-app{background:#050505!important;color:#f7f7f7!important;background-image:none!important}
.trc-header{background:rgba(5,5,5,.97)!important;border-bottom:1px solid #292929!important;box-shadow:0 5px 22px #0007!important}
.trc-menu-toggle,.trc-head-actions button{background:#151515!important;color:#fff!important;border:1px solid #303030!important;border-radius:15px!important}
.trc-menu-panel,.trc-search{background:#111!important;border:1px solid #343434!important;box-shadow:0 18px 45px #000b!important}
.trc-menu-link{color:#f5f5f5!important}.trc-menu-link:hover,.trc-menu-link:active{background:#ec247c22!important}
.trc-main{color:#f7f7f7!important}
.trc-home-heading h1,.trc-home-heading h2,.trc-section-title h2,.trc-library-head h1,.trc-library-subtitle{color:#fff!important}
.trc-home-heading button,.trc-home-heading a,.trc-section-title a{color:#ff5a9f!important}
.trc-live-pill,.trc-feature-banner{background:linear-gradient(125deg,#3a1025,#9f174f 58%,#ed247c)!important;border:1px solid #f34b91!important;box-shadow:0 12px 30px #ec247c24!important}
.trc-trend-card,.trc-recommend-item,.trc-song,.trc-playlist,.trc-library-row,.trc-category,.trc-player,.trc-profile-card{background:#111!important;color:#f7f7f7!important;border:1px solid #303030!important;box-shadow:0 8px 24px #0005!important;border-radius:16px!important}
.trc-trend-card small,.trc-recommend-item small,.trc-song-info small,.trc-playlist small,.trc-library-row small,.trc-library-note{color:#aaa!important}
.trc-play,.trc-controls button.main,.trc-profile-card button,.trc-library-tabs button.selected{background:#ec247c!important;color:#fff!important;box-shadow:0 5px 18px #ec247c38!important}
.trc-library-tabs button{background:#202020!important;color:#eee!important}
.trc-bottom{background:rgba(12,12,12,.97)!important;border-top:1px solid #303030!important;box-shadow:0 -8px 28px #0007!important}
.trc-bottom button{color:#858585!important}.trc-bottom button.active{color:#ff4d9b!important}
.trc-toast{background:#1b1b1b!important;border:1px solid #ec247c55!important}
.trc-player{background:linear-gradient(160deg,#191016,#101010 70%)!important}
.trc-progress{accent-color:#ec247c!important}.trc-controls .main{background:#ec247c!important;color:#fff!important}
.trc-demo-card{border-color:#ec247c!important;background:linear-gradient(160deg,#171014,#090909 70%)!important;box-shadow:0 0 0 1px #ec247c22,0 12px 38px #000b!important}
.trc-demo-card .trc-eyebrow,.trc-demo-card .trc-lyrics span:first-child{color:#ff6aa8!important}
.trc-demo-card .trc-action.liked span{color:#ec247c!important}
.trc-header-quick-actions .trc-header-icon{background:linear-gradient(145deg,#24111b,#111)!important;color:#ff8cba!important;border-color:#71304b!important;box-shadow:inset 0 1px 0 #ffffff0c,0 5px 18px #0006!important}
.trc-header-quick-actions #trcNotifications:after{background:#ec247c!important;box-shadow:0 0 8px #ec247c!important}
.trc-profile-card .trc-profile-avatar.trc-profile-logo{border-color:#ec247c66!important;box-shadow:0 8px 30px #ec247c24!important}
@media(max-width:600px){.trc-header{background:#050505!important}.trc-bottom{background:#0b0b0b!important}}


    /* Compact mobile profile login + TRC full form */
    #screen-profile .trc-auth-brandline{
      margin:0 auto 9px!important;color:#ec2580!important;
