    #screen-profile .trc-auth-divider:after{background:linear-gradient(90deg,#e45cae,transparent)}
    #screen-profile .trc-auth-social{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
    #screen-profile .trc-auth-social button{
      min-width:0;min-height:94px;display:flex;flex-direction:column;align-items:center;
