/* FIX: keep the floating bottom navigation anchored to the visible screen */
@media (max-width: 600px) {
  html, body { min-height: 100%; }
  .trc-app { padding-bottom: 112px !important; }
  .trc-bottom {
    position: fixed !important;
    left: 4% !important;
    right: 4% !important;
    bottom: 8px !important;
    width: 92% !important;
    height: 68px !important;
    margin: 0 !important;
    box-sizing: border-box !important;
    z-index: 99999 !important;
    transform: none !important;
    -webkit-transform: none !important;
    padding: 5px 8px !important;
    padding-bottom: 5px !important;
    will-change: auto !important;
  }
}

/* FIX: continue the violet home background behind the fixed bottom navigation */
    body:has(#screen-home.active),
    html:has(#screen-home.active){
