      display:block!important;position:static!important;float:none!important;transform:none!important;
      width:100%!important;max-width:none!important;height:auto!important;min-height:0!important;
      margin:0!important;padding:0!important;overflow:visible!important;opacity:1!important;
      visibility:visible!important;pointer-events:auto!important;background:transparent!important;border:0!important;box-shadow:none!important
    }
    html.trc-login-page body #Blog1 .post-title,html.trc-login-page body #Blog1 .post-header,
    html.trc-login-page body #Blog1 .post-footer,html.trc-login-page body #Blog1 .date-header,
    html.trc-login-page body #Blog1 .post-share-buttons,
    body.trc-login-page #Blog1 .post-title,body.trc-login-page #Blog1 .post-header,
