    .trc-profile-card p{color:#bdb6c9;line-height:1.5}
    .trc-profile-login-link{display:inline-flex;align-items:center;justify-content:center;margin-top:12px;padding:13px 24px;border-radius:13px;background:linear-gradient(120deg,#8f4bc4,#bd83ff);color:#fff!important;font-weight:800}

body.script:
//

/* Load Blogger posts into TRC; open the matching post inside the app shell. */
function trcLoadBloggerPosts(){
  var box=document.getElementById('trcBloggerPosts');
  var path=window.location.pathname.replace(/\/+$/,'');
  var isPost=/\/\d{4}\/\d{2}\/[^/]+\.html$/i.test(path);
  var start=1,pageSize=isPost?150:50,total=0,matched=null;
  function postUrl(entry){
    var url='';
    (entry.link||[]).some(function(link){
      if(link.rel==='alternate'){url=link.href;return true;}
      return false;
    });
    return url;
  }
  function renderPost(entry){
    var title=(entry.title&&entry.title.$t)||'Untitled';
    var bloggerAuthor=(entry.author&&entry.author[0]&&entry.author[0].name&&entry.author[0].name.$t)||'';
    var content=(entry.content&&entry.content.$t)||(entry.summary&&entry.summary.$t)||'';
    var doc=new DOMParser().parseFromString(content,'text/html');
    var rawText=(doc.body&&doc.body.textContent)||'';
    var artist='';
    var artistMatch=rawText.match(/(?:^|\\n|\\b)(?:primary\\s+)?artist(?:\\s+name)?\\s*[:：–-]\\s*([^\\n|;]+)/i)
      ||rawText.match(/(?:^|\\n|\\b)(?:singer|performer)\\s*[:：–-]\\s*([^\\n|;]+)/i);
    if(artistMatch)artist=artistMatch[1].replace(/<[^>]*>/g,'').trim();

    /* Read the structured "Artists" metadata block used in TRC song posts.
       The previous parser only recognized "Artist: NAME" text and missed
       posts where artist names are listed under an "Artists" heading. */
    if(!artist){
      var blockText=content
        .replace(/<br\s*\/?\s*>/gi,'\n')
        .replace(/<\/(?:p|div|li|h[1-6]|section|tr|td)>/gi,'\n');
      var blockDoc=new DOMParser().parseFromString(blockText,'text/html');
      var lines=(blockDoc.body.textContent||'').split(/[\r\n]+/)
        .map(function(line){return line.replace(/\s+/g,' ').trim();})
        .filter(Boolean);
      var artistHeading=-1;
      for(var ai=0;ai<lines.length;ai++){
        if(/^artists?\s*:?$/i.test(lines[ai])){artistHeading=ai;break;}
      }
      if(artistHeading>=0){
        var names=[];
        var stop=/^(composition\s*&\s*lyrics|production\s*&\s*engineering|credits?|source|release(?:\s+information)?|track\s+details|lyrics)$/i;
        var role=/^(main|featured|primary|guest)\s+artist$|^(artist|singer|vocalist|performer)$/i;
        for(var aj=artistHeading+1;aj<lines.length;aj++){
          var line=lines[aj];
          if(stop.test(line))break;
          if(role.test(line))continue;
          if(/^(?:label|publisher|record label)\s*:/i.test(line))break;
          if(line.length>0 && line.length<100 && !/^(?:composer|producer|writer|remixer|featuring)$/i.test(line)){
            names.push(line);
          }
          if(names.length>=5)break;
        }
        if(names.length)artist=names.join(' · ');
      }
    }
    if(!artist && entry.category && entry.category.length){
      var labels=entry.category.map(function(c){return c.term||'';}).filter(Boolean);
      var artistLabel=labels.find(function(label){return /artist|singer|performer/i.test(label);});
      if(artistLabel)artist=artistLabel.replace(/^(artist|singer|performer)\\s*[:：-]?\\s*/i,'').trim();
    }
    if(!artist)artist='Artist details unavailable';
    var image=doc.querySelector('img');
    var date=(entry.published&&entry.published.$t)||'';
    var dateLabel=date?new Date(date).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'';
    var main=document.querySelector('.trc-main');
    if(!main)return;
    main.innerHTML='';
    var article=document.createElement('article');
    article.className='trc-single-post';

    var top=document.createElement('div');
    top.className='trc-single-top';
    top.innerHTML='<span>TRC MUSIC</span><span>NOW PLAYING</span>';
    article.appendChild(top);

    var artwork=document.createElement('div');
    artwork.className='trc-artwork-wrap';
    var cover=document.createElement('img');
    cover.className='trc-single-cover';
    cover.src=image?image.src:'https://cdn.jsdelivr.net/gh/arunadh007/arunadh007.github.io@main/trc-pwa/icons/trc-192.png';
    cover.alt=title+' artwork';
    artwork.appendChild(cover);
    var lyricsHint=document.createElement('button');
    lyricsHint.type='button';lyricsHint.className='trc-lyrics-hint';lyricsHint.textContent='Swipe for lyrics ›';
    artwork.appendChild(lyricsHint);
    var lyricsOverlay=document.createElement('div');lyricsOverlay.className='trc-lyrics-overlay';
    var lyricsTitle=document.createElement('h3');lyricsTitle.textContent='LYRICS';
    var lyricsCopy=document.createElement('div');lyricsCopy.className='trc-lyrics-copy';
    var lyricsText='';
    var lyricHeading=Array.prototype.slice.call(doc.querySelectorAll('h1,h2,h3,h4,strong,b')).find(function(el){return /^(lyrics|song lyrics)$/i.test((el.textContent||'').trim());});
    if(lyricHeading){
      var node=lyricHeading.parentElement.nextElementSibling;
      var chunks=[];
      while(node && !/^H[1-4]$/.test(node.tagName)){
        var t=(node.innerText||node.textContent||'').trim();if(t)chunks.push(t);
        node=node.nextElementSibling;
      }
      lyricsText=chunks.join('\\n');
    }
    lyricsCopy.textContent=lyricsText||'Lyrics will be available soon.';
    var lyricsClose=document.createElement('button');lyricsClose.type='button';lyricsClose.className='trc-lyrics-close';lyricsClose.textContent='Back to artwork';
    lyricsOverlay.appendChild(lyricsTitle);lyricsOverlay.appendChild(lyricsCopy);lyricsOverlay.appendChild(lyricsClose);
    artwork.appendChild(lyricsOverlay);
    function toggleLyrics(show){artwork.classList.toggle('show-lyrics',show);}
    lyricsHint.addEventListener('click',function(){toggleLyrics(true);});
    lyricsClose.addEventListener('click',function(){toggleLyrics(false);});
    var touchStartY=0;
    artwork.addEventListener('touchstart',function(e){if(e.touches&&e.touches[0])touchStartY=e.touches[0].clientY;},{passive:true});
    artwork.addEventListener('touchend',function(e){if(!e.changedTouches||!e.changedTouches[0])return;var delta=touchStartY-e.changedTouches[0].clientY;if(delta>35)toggleLyrics(true);else if(delta< -35)toggleLyrics(false);},{passive:true});
    article.appendChild(artwork);
    if(image)image.remove();

    var heading=document.createElement('div');
    heading.className='trc-single-heading';
    var h=document.createElement('h1');h.textContent=title;
    var meta=document.createElement('p');meta.textContent=artist+(dateLabel?' · '+dateLabel:'');
    heading.appendChild(h);heading.appendChild(meta);article.appendChild(heading);

    var body=document.createElement('div');
    body.className='trc-single-content';
    body.innerHTML=doc.body.innerHTML;
    body.querySelectorAll('img').forEach(function(img){img.remove();});

    /* Reformat Spotify-style metadata; keep playback controls out of this section. */
    (function formatSpotifyMetadata(){
      var headings=Array.prototype.slice.call(body.querySelectorAll('h2,h3,h4'));
      /* Keep only the Artist metadata block: remove title, Play Song and release-date
         content that appears before the Artist heading in the source post body. */
      var artistHeading=headings.find(function(h){return /^artists?$/i.test((h.textContent||'').replace(/\\s+/g,' ').trim());});
      if(artistHeading){
        var trimRange=document.createRange();
        trimRange.selectNodeContents(body);
        trimRange.setEndBefore(artistHeading);
        trimRange.deleteContents();
        headings=Array.prototype.slice.call(body.querySelectorAll('h2,h3,h4'));
      }
      var roleWords=['Main Artist','Featured Artist','Composer','Lyricist','Producer','Co-Producer','Executive Producer','Mixing Engineer','Mastering Engineer','Recording Engineer','Arranger','Publisher','Record Label'];
      function clean(t){return (t||'').replace(/\s+/g,' ').trim();}
      function splitPeople(raw,defaultRole){
        raw=clean(raw);
        var rolePattern=/(Main Artist|Featured Artist|Co-Producer|Executive Producer|Mixing Engineer|Mastering Engineer|Recording Engineer|Producer|Composer|Lyricist|Arranger|Publisher|Record Label)/ig;
        var out=[],last=0,m;
        while((m=rolePattern.exec(raw))!==null){
          var person=clean(raw.slice(last,m.index)).replace(/^[\s|,:;·-]+|[\s|,:;·-]+$/g,'');
          if(person)out.push({name:person,role:m[0]});
          last=rolePattern.lastIndex;
        }
        var tail=clean(raw.slice(last)).replace(/^[\s|,:;·-]+|[\s|,:;·-]+$/g,'');
        if(tail)out.push({name:tail,role:defaultRole||''});
        if(!out.length && raw)out.push({name:raw,role:defaultRole||''});
        return out;
      }
      headings.forEach(function(head){
        var label=clean(head.textContent),key=label.toLowerCase().replace(/&/g,'and');
        var isArtist=/^artists?$/.test(key);
        var isComposition=/^composition\s*and\s*lyrics?$/.test(key);
        var isProduction=/^production\s*and\s*engineering$/.test(key);
        var isSources=/^sources?$/.test(key);
        if(!(isArtist||isComposition||isProduction||isSources))return;
        var section=document.createElement('section');section.className='trc-meta-section';
        var title=document.createElement('h2');
        title.textContent=isArtist?'Artist':isComposition?'Composition and lyrics':isProduction?'Production & Engineering':'Sources';
        section.appendChild(title);
        var nodes=[],cursor=head.nextElementSibling;
        while(cursor&&!/^(H2|H3|H4)$/.test(cursor.tagName)){var next=cursor.nextElementSibling;if(clean(cursor.textContent))nodes.push(cursor);cursor=next;}
        var raw=nodes.map(function(n){return clean(n.innerText||n.textContent);}).join(' ');
        /* Drop duplicated listen/play controls and their empty wrapper paragraphs. */
        nodes.forEach(function(n){
          n.querySelectorAll('a,button').forEach(function(el){
            if(/play song|listen now|^play$|^listen$/i.test(clean(el.textContent))){var wrap=el.closest('p');if(wrap&&clean(wrap.textContent).replace(clean(el.textContent),'')==='')wrap.remove();else el.remove();}
          });
        });
        raw=nodes.map(function(n){return clean(n.textContent);}).join(' ');
        if(isArtist||isComposition||isProduction){
          var defaultRole=isArtist?'Main Artist':isComposition?'Composer':'Producer';
          var people=splitPeople(raw,defaultRole);
          people.forEach(function(item){
            if(!item.name)return;
            var row=document.createElement('div');row.className='trc-meta-row';
            var person=document.createElement('div');person.className='trc-meta-person';
            var name=document.createElement('span');name.className='trc-meta-name';name.textContent=item.name;person.appendChild(name);
            if(item.role){var role=document.createElement('small');role.textContent=item.role;person.appendChild(role);}
            var avatar=document.createElement('span');avatar.className='trc-meta-avatar';avatar.textContent=item.name.trim().charAt(0).toUpperCase();row.appendChild(avatar);
            row.appendChild(person);

            section.appendChild(row);
          });
        }else{
          nodes.forEach(function(n){var txt=clean(n.textContent);if(txt){var p=document.createElement('p');p.className='trc-meta-copy';p.textContent=txt;section.appendChild(p);}});
        }
        if(section.children.length>1){
          head.parentNode.insertBefore(section,head);head.remove();
          nodes.forEach(function(n){if(n.parentNode)n.remove();});
        }
      });
      /* Remove any leftover Play Song/Listen button from metadata body. */
      body.querySelectorAll('a,button').forEach(function(el){
        if(/^(play song|listen now|play|listen)$/i.test(clean(el.textContent))){var p=el.closest('p');if(p&&clean(p.textContent)===clean(el.textContent))p.remove();else el.remove();}
      });
    })();

    /* Play/listen links belong only in the main player area, not inside metadata. */
    body.querySelectorAll('a,button').forEach(function(el){
      var label=(el.textContent||'').replace(/\\s+/g,' ').trim().toLowerCase();
      if(/^(play song|listen now|play|listen)$/.test(label))el.remove();
    });
    body.querySelectorAll('iframe').forEach(function(frame){frame.remove();});

    /* Detect an MP3/audio source if one is added to the Blogger post later. */
    var audioSource='';
    var audioNode=body.querySelector('audio source[src],audio[src]');
    if(audioNode)audioSource=audioNode.getAttribute('src')||'';
    if(!audioSource){
      body.querySelectorAll('a[href]').forEach(function(a){
        var href=a.getAttribute('href')||'';
        if(!audioSource && /\.(mp3|m4a|wav|ogg|aac)(\?|#|$)/i.test(href))audioSource=href;
      });
    }
    body.querySelectorAll('audio,video').forEach(function(el){el.remove();});

    var player=document.createElement('div');
    player.className='trc-single-player';
    var status=document.createElement('div');
    status.className='trc-player-status';
    status.innerHTML='<i></i><span>'+(audioSource?'READY TO PLAY':'AUDIO WILL BE ADDED SOON')+'</span>';
    player.appendChild(status);

    var audio=document.createElement('audio');
    audio.preload='metadata';
    if(audioSource)audio.src=audioSource;
    var progress=document.createElement('input');
    progress.className='trc-player-progress';progress.type='range';progress.min='0';progress.max='100';progress.value='0';
    progress.setAttribute('aria-label','Track progress');
    var times=document.createElement('div');times.className='trc-player-times';
    var current=document.createElement('span');current.textContent='0:00';
    var duration=document.createElement('span');duration.textContent='0:00';
    times.appendChild(current);times.appendChild(duration);
    player.appendChild(progress);player.appendChild(times);

    var controls=document.createElement('div');controls.className='trc-player-controls';
    var previous=document.createElement('button');previous.type='button';previous.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M6 5h2v14H6zm13 1v12L9 12z"/></svg>';previous.disabled=true;previous.setAttribute('aria-label','Previous track');
    var play=document.createElement('button');play.type='button';play.className='trc-single-play';play.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg>';play.setAttribute('aria-label','Play');
    var next=document.createElement('button');next.type='button';next.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="currentColor" d="M16 5h2v14h-2zM5 6v12l10-6z"/></svg>';next.disabled=true;next.setAttribute('aria-label','Next track');
    if(!audioSource)play.disabled=true;
    controls.appendChild(previous);controls.appendChild(play);controls.appendChild(next);
    var commentLink=document.createElement('button');
    commentLink.type='button';
    commentLink.className='trc-comment-icon';
    commentLink.setAttribute('aria-label','Comments');commentLink.title='Comments';
    commentLink.addEventListener('click',function(ev){
      ev.preventDefault();ev.stopPropagation();
      var panel=article.querySelector('.trc-comments-panel');
      if(!panel){
        panel=document.createElement('section');
        panel.className='trc-comments-panel is-open';
        panel.innerHTML='<div class="trc-comments-heading">Comments</div><div class="trc-comments-content"><p class="trc-comments-loading">Loading comments…</p></div>';
        player.insertAdjacentElement('afterend',panel);
        var content=panel.querySelector('.trc-comments-content');
        var attempts=0;
        function attachNativeComments(){
          /* Blogger may use a different wrapper for legacy and threaded comments. */
          var nativeComments=document.querySelector('.blogger-hidden #Blog1 #comments')
            ||document.querySelector('#Blog1 #comments')
            ||document.querySelector('.blogger-hidden section.comments')
            ||document.querySelector('section#comments')
            ||document.querySelector('.comments.threaded');
          if(nativeComments){
            nativeComments.style.setProperty('display','block','important');
            nativeComments.style.setProperty('visibility','visible','important');
            nativeComments.style.setProperty('opacity','1','important');
            nativeComments.style.setProperty('position','relative','important');
            nativeComments.style.setProperty('left','auto','important');
            nativeComments.style.setProperty('width','100%','important');
            nativeComments.style.setProperty('height','auto','important');
            nativeComments.style.setProperty('max-width','100%','important');
            nativeComments.style.setProperty('margin','0','important');
            nativeComments.style.setProperty('padding','0','important');
            content.replaceChildren(nativeComments);
            var form=nativeComments.querySelector('.comment-form');
            if(form)form.style.setProperty('display','block','important');
            var editor=nativeComments.querySelector('#comment-editor');
            if(editor){editor.style.setProperty('display','block','important');editor.style.setProperty('width','100%','important');}
          }else if(attempts++<40){
            setTimeout(attachNativeComments,250);
          }else{
            content.innerHTML='<p class="trc-comments-loading">Comments are temporarily unavailable. Please try again shortly.</p>';
          }
        }
        attachNativeComments();
      }else{
        panel.classList.toggle('is-open');
      }
      if(panel.classList.contains('is-open'))setTimeout(function(){panel.scrollIntoView({behavior:'smooth',block:'start'});},80);
    });
    commentLink.innerHTML='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M14 9h36a7 7 0 0 1 7 7v25a7 7 0 0 1-7 7H29L13 59V48h-2a7 7 0 0 1-7-7V16a7 7 0 0 1 7-7Z"/></svg>';
    controls.insertBefore(commentLink,previous);
    var whatsappLink=document.createElement('a');
    whatsappLink.className='trc-whatsapp-share';
    whatsappLink.href='https://wa.me/?text='+encodeURIComponent(title+' — Listen on TRC Music: '+postUrl(entry));
    whatsappLink.target='_blank';whatsappLink.rel='noopener noreferrer';
    whatsappLink.setAttribute('aria-label','Share song on WhatsApp');whatsappLink.title='Share on WhatsApp';
    whatsappLink.innerHTML='<svg viewBox="0 0 64 64" aria-hidden="true"><path d="M54 29a22 22 0 0 1-32 20L8 53l4-13A22 22 0 1 1 54 29Z"/><path d="M22 19c-2 2-3 5-2 8 3 9 10 16 19 19 3 1 6 0 8-2l3-4-10-6-4 4c-4-2-7-5-9-9l4-4-6-10-3 4Z"/></svg>';
    controls.appendChild(whatsappLink);
    player.appendChild(controls);
    var note=document.createElement('p');note.className='trc-single-note';
    note.textContent=audioSource?'Enjoy this release on TRC Music':'The custom player is ready. Add an MP3 link to this post to enable playback.';
    player.appendChild(note);player.appendChild(audio);
    article.appendChild(player);

    function clock(value){if(!isFinite(value))return '0:00';var m=Math.floor(value/60),sec=Math.floor(value%60);return m+':'+(sec<10?'0':'')+sec;}
    if(audioSource){
      audio.addEventListener('loadedmetadata',function(){duration.textContent=clock(audio.duration);});
      audio.addEventListener('timeupdate',function(){current.textContent=clock(audio.currentTime);if(audio.duration)progress.value=(audio.currentTime/audio.duration)*100;});
      audio.addEventListener('play',function(){play.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 5h4v14H6zm8 0h4v14h-4z"/></svg>';status.querySelector('span').textContent='NOW PLAYING';});
      audio.addEventListener('pause',function(){play.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg>';if(!audio.ended)status.querySelector('span').textContent='PAUSED';});
      audio.addEventListener('ended',function(){play.innerHTML='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5v14l11-7z"/></svg>';status.querySelector('span').textContent='PLAYBACK FINISHED';progress.value=0;});
      play.addEventListener('click',function(){if(audio.paused)audio.play().catch(function(){status.querySelector('span').textContent='AUDIO COULD NOT PLAY';});else audio.pause();});
      progress.addEventListener('input',function(){if(audio.duration)audio.currentTime=(Number(progress.value)/100)*audio.duration;});
    }

    var details=document.createElement('details');
    details.className='trc-single-details';
    var summary=document.createElement('summary');summary.textContent='Track details & credits';
    details.appendChild(summary);
    details.appendChild(body);
    article.appendChild(details);

    main.appendChild(article);
    document.title=title+' | TRC Music';
  }
  function loadPage(){
    return fetch('/feeds/posts/default?alt=json&max-results='+pageSize+'&start-index='+start)
      .then(function(r){if(!r.ok)throw new Error('Blogger feed request failed');return r.json();})
      .then(function(data){
        var entries=(data&&data.feed&&data.feed.entry)||[];
        entries.forEach(function(entry){
          var url=postUrl(entry);
          if(isPost && url){
            try{
              var u=new URL(url,window.location.origin);
              if(u.pathname.replace(/\/+$/,'')===path)matched=entry;
            }catch(ignore){}
          }
          if(box && !isPost){
            var title=(entry.title&&entry.title.$t)||'Untitled';
            var bloggerAuthor=(entry.author&&entry.author[0]&&entry.author[0].name&&entry.author[0].name.$t)||'';
            var content=(entry.content&&entry.content.$t)||(entry.summary&&entry.summary.$t)||'';
            var imageMatch=content.match(/<img[^>]+src=["']([^"']+)["']/i);
            var image=(imageMatch&&imageMatch[1])||'';
            var date=(entry.published&&entry.published.$t)||'';
            var dateLabel=date?new Date(date).toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'}):'';
            var a=document.createElement('a');a.className='trc-recommend-item';a.href=url||'#';a.style.textDecoration='none';
            var img=document.createElement('img');img.alt=title+' artwork';
            img.src=image||'https://cdn.jsdelivr.net/gh/arunadh007/arunadh007.github.io@main/trc-pwa/icons/trc-192.png';
            var info=document.createElement('span');var name=document.createElement('b');name.textContent=title;
            var meta=document.createElement('small');meta.textContent=bloggerAuthor+(dateLabel?' · '+dateLabel:'');
            info.appendChild(name);info.appendChild(meta);
            var arrow=document.createElement('i');arrow.textContent='›';
            a.appendChild(img);a.appendChild(info);a.appendChild(arrow);box.appendChild(a);
          }
        });
        total+=entries.length;
        if(isPost && entries.length===pageSize){start+=pageSize;return loadPage();}
        if(isPost){
          if(matched)renderPost(matched);
          else document.querySelector('.trc-main').innerHTML='<div class="trc-library-note">This Blogger post could not be found in the public feed. Make sure it is published.</div>';
        }else if(box && !total)box.innerHTML='<div class="trc-library-note">No published posts found yet.</div>';
      });
  }
  if(box && !isPost)box.innerHTML='';
  loadPage().catch(function(){
    if(isPost){
      var main=document.querySelector('.trc-main');
      if(main)main.innerHTML='<div class="trc-library-note">Could not load this song post. Please check that the Blogger post is public.</div>';
    }else if(box)box.innerHTML='<div class="trc-library-note">Music releases are temporarily unavailable. Please refresh in a moment.</div>';
  });
}
document.addEventListener('DOMContentLoaded',trcLoadBloggerPosts);

document.addEventListener('DOMContentLoaded',function(){
  var bell=document.getElementById('trcNotifications');
  var panel=document.getElementById('trcNotificationPanel');
  var list=document.getElementById('trcNotificationItems');
  if(!bell||!panel||!list)return;
  var loaded=false;
  function addEntries(feed,kind){
    return ((feed&&feed.feed&&feed.feed.entry)||[]).map(function(e){
      var link=(e.link||[]).filter(function(x){return x.rel==='alternate';})[0];
      return {title:(e.title&&e.title.$t)||'Untitled',url:link&&link.href,date:(e.published&&e.published.$t)||(e.updated&&e.updated.$t),kind:kind};
    });
  }
  function load(){
    if(loaded)return;loaded=true;
    list.innerHTML='<p class="trc-notification-empty">Loading updates…</p>';
    Promise.all([
      fetch('/feeds/posts/default?alt=json&max-results=20').then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(d){return addEntries(d,'New release');}).catch(function(){return [];}),
      fetch('/feeds/pages/default?alt=json&max-results=20').then(function(r){if(!r.ok)throw 0;return r.json();}).then(function(d){return addEntries(d,'Page update');}).catch(function(){return [];})
    ]).then(function(groups){
      var items=groups[0].concat(groups[1]).filter(function(x){return x.url;});
      items.sort(function(a,b){return new Date(b.date||0)-new Date(a.date||0);});
      list.innerHTML='';
      if(!items.length){list.innerHTML='<p class="trc-notification-empty">No updates available right now.</p>';return;}
      items.slice(0,15).forEach(function(item){
        var a=document.createElement('a');a.className='trc-notification-item';a.href=item.url;
        a.appendChild(document.createTextNode(item.title));
        var small=document.createElement('small');small.textContent=item.kind+' · '+(item.date?new Date(item.date).toLocaleDateString():'');a.appendChild(small);list.appendChild(a);
      });
    });
  }
  bell.addEventListener('click',function(e){e.preventDefault();e.stopPropagation();panel.hidden=!panel.hidden;if(!panel.hidden)load();});
  document.addEventListener('click',function(e){if(!panel.contains(e.target)&&!bell.contains(e.target))panel.hidden=true;});
});

document.addEventListener('DOMContentLoaded',function(){
  if(new URLSearchParams(window.location.search).get('trc-comments')==='1'){
    document.body.classList.add('trc-comments-embed');
    return;
  }
});
document.addEventListener('DOMContentLoaded',function(){
  if(!/^(#comments|#comment-form)$/i.test(window.location.hash))return;
  document.body.classList.add('trc-comments-route');
  var tries=0;
  function revealNativeComments(){
    var section=document.querySelector('.blogger-hidden');
    var comments=document.querySelector('.blogger-hidden #comments');
    if(section){
      section.style.setProperty('display','block','important');
      section.style.setProperty('position','relative','important');
      section.style.setProperty('left','0','important');
      section.style.setProperty('top','auto','important');
      section.style.setProperty('width','100%','important');
      section.style.setProperty('height','auto','important');
      section.style.setProperty('overflow','visible','important');
      section.style.setProperty('opacity','1','important');
      section.style.setProperty('pointer-events','auto','important');
      section.style.setProperty('z-index','1','important');
    }
    if(comments){
      comments.style.setProperty('display','block','important');
      comments.style.setProperty('visibility','visible','important');
      comments.style.setProperty('opacity','1','important');
      setTimeout(function(){comments.scrollIntoView({behavior:'smooth',block:'start'});},250);
      return;
    }
    if(++tries<35)setTimeout(revealNativeComments,200);
  }
  setTimeout(revealNativeComments,250);
});


function trcToast(msg){var t=document.getElementById('trcToast');t.textContent=msg;t.classList.add('show');window.setTimeout(function(){t.classList.remove('show')},1800)}
function trcShowScreen(name){document.querySelectorAll('.trc-screen').forEach(function(s){s.classList.remove('active')});var target=document.getElementById('screen-'+name);if(target)target.classList.add('active');document.querySelectorAll('.trc-bottom button').forEach(function(b){b.classList.toggle('active',b.getAttribute('data-screen')===name)})}
document.querySelectorAll('.trc-bottom button').forEach(function(b){b.addEventListener('click',function(){trcShowScreen(b.getAttribute('data-screen'))})});
function trcMenuGo(name){trcShowScreen(name);document.getElementById('trcMenuPanel').classList.remove('open')}
function trcToggleMenu(){document.getElementById('trcMenuPanel').classList.toggle('open')}
document.getElementById('trcMenuToggle').addEventListener('click',trcToggleMenu);
document.addEventListener('click',function(e){var panel=document.getElementById('trcMenuPanel');if(!panel.contains(e.target)&&e.target.id!=='trcMenuToggle'){panel.classList.remove('open')}});

function trcLike(btn){btn.classList.toggle('liked');var s=btn.querySelector('span');if(s)s.textContent=btn.classList.contains('liked')?'♥':'♡';trcToast(btn.classList.contains('liked')?'Added to Liked':'Removed from Liked')}
function trcDemoComment(){trcToast('Comments will be connected when the backend is added')}
function trcShareDemo(title){var url=window.location.href;if(navigator.share){navigator.share({title:title+' | The Retro Collection',url:url}).catch(function(){})}else if(navigator.clipboard){navigator.clipboard.writeText(url).then(function(){trcToast('Song link copied')},function(){trcToast('Use your browser share button')})}else{trcToast('Use your browser share button')}}
function trcWhatsAppShare(title){var url=window.location.href;var message=title+' — Arun Adhikari\nListen on TRC Music: '+url;window.open('https://wa.me/?text='+encodeURIComponent(message),'_blank','noopener');}
function trcHeaderPlayToggle(){var b=document.getElementById('trcHeaderPlay');if(!b)return;b.classList.toggle('playing');b.querySelector('span').textContent=b.classList.contains('playing')?'Ⅱ':'▶';var main=document.getElementById('trcMainPlay');if(main)main.textContent=b.classList.contains('playing')?'Ⅱ':'▶';trcToast('Audio playback will connect with the backend')}
function trcOpenDiscover(){trcShowScreen('discover')}
function trcSelectSong(title,artist){document.getElementById('trcPlayerTitle').textContent=title;document.getElementById('trcPlayerArtist').textContent=artist;trcShowScreen('player')}
function trcTogglePlay(){var b=document.getElementById('trcMainPlay');if(b)b.textContent=b.textContent==='▶'?'Ⅱ':'▶';trcToast('Audio playback will connect with the backend')}
function trcBottomPlayToggle(){trcHeaderPlayToggle()}
document.getElementById('trcSearch').addEventListener('input',function(){var q=this.value.toLowerCase();document.querySelectorAll('.trc-song').forEach(function(s){s.style.display=s.textContent.toLowerCase().indexOf(q)>-1?'':'none'})});

/* Swipe the album cover sideways to reveal the lyrics panel */
document.querySelectorAll('.trc-demo-card').forEach(function(card){
  var img=card.querySelector('.trc-cover-img');
  var lyrics=card.querySelector('.trc-lyrics');
  if(!img||!lyrics)return;
  var stage=document.createElement('div');
  stage.className='trc-swipe-stage';
  img.parentNode.insertBefore(stage,img);
  stage.appendChild(img);
  stage.appendChild(lyrics);
  var hint=document.createElement('span');
  hint.className='trc-swipe-hint';
  hint.textContent='Swipe for lyrics  ›';
  stage.appendChild(hint);
  var startX=0,startY=0;
  stage.addEventListener('touchstart',function(e){
    if(!e.touches||!e.touches.length)return;
    startX=e.touches[0].clientX;startY=e.touches[0].clientY;
  },{passive:true});
  stage.addEventListener('touchend',function(e){
    if(!e.changedTouches||!e.changedTouches.length)return;
    var dx=e.changedTouches[0].clientX-startX;
    var dy=e.changedTouches[0].clientY-startY;
    if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.25){
      card.classList.toggle('show-lyrics',dx<0);
    }
  },{passive:true});
  stage.addEventListener('click',function(){
    if(window.matchMedia('(hover: hover) and (pointer: fine)').matches){
      card.classList.toggle('show-lyrics');
    }
  });
});

