(function(){
  if(!/^\/p\/login\.html\/?$/i.test(window.location.pathname)) return;
  function revealLoginPage(){
    document.documentElement.classList.add('trc-login-page');
    document.body.classList.add('trc-login-page');
    var app=document.querySelector('.trc-app');
    if(app) app.style.setProperty('display','none','important');
    var toast=document.getElementById('trcToast');
    if(toast) toast.style.setProperty('display','none','important');
    var blog=document.getElementById('Blog1');
    var main=document.getElementById('main');
    var target=blog||main;
    if(!target) return;
    var node=target;
    while(node && node!==document.body){
      ['display','position','left','top','width','max-width','height','min-height','margin','padding','overflow','opacity','visibility','pointer-events','z-index','transform'].forEach(function(prop){
        var vals={display:'block',position:'static',left:'auto',top:'auto',width:'100%', 'max-width':'none',height:'auto','min-height':'0',margin:'0',padding:'0',overflow:'visible',opacity:'1',visibility:'visible','pointer-events':'auto','z-index':'auto',transform:'none'};
        node.style.setProperty(prop,vals[prop],'important');
      });
      node=node.parentElement;
    }
    var selectors=['.widget-content','.post-outer-container','.post-outer','.post','.post-body','.entry-content','article'];
    selectors.forEach(function(sel){
      target.querySelectorAll(sel).forEach(function(el){
        el.style.setProperty('display','block','important');
        el.style.setProperty('position','static','important');
        el.style.setProperty('width','100%','important');
        el.style.setProperty('max-width','none','important');
        el.style.setProperty('height','auto','important');
        el.style.setProperty('min-height','0','important');
        el.style.setProperty('overflow','visible','important');
        el.style.setProperty('opacity','1','important');
        el.style.setProperty('visibility','visible','important');
        el.style.setProperty('pointer-events','auto','important');
      });
    });
    var body=target.querySelector('.post-body');
    if(body){body.style.setProperty('color','#f7f2ff','important');body.style.setProperty('padding','0','important');}
  }
  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',revealLoginPage);
  else revealLoginPage();
  window.addEventListener('load',revealLoginPage);
})();
